output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles, especially corridors with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "single_file_width": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file_width",
            "between_opposing_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_into_single_file_aisle",
    "text": "A shopper may not push a cart from an open aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_width": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file_width",
            "between_opposing_shelves"
          ]
        }
      },
      "events": {
        "cart_enters_single_file_shelf_aisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_enters_single_file_shelf_aisle"
    }
  },
  {
    "id": "park_before_narrow_aisle",
    "text": "Upon arriving with a cart at the wide mouth of a single-file shelf aisle, the shopper is obliged to park the cart before entering.",
    "abstraction": {
      "state_properties": {
        "wide_open_cell": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "single_file_aisle_mouth": {
          "and": [
            "at(3,3)",
            "wide_open_cell"
          ]
        },
        "cart_at_single_file_aisle_mouth": {
          "and": [
            "single_file_aisle_mouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "arrive_at_single_file_aisle_mouth_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "cart_at_single_file_aisle_mouth"
        },
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "single_file_aisle_mouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_single_file_aisle_mouth_with_cart",
      "discharge": "park_cart"
    }
  },
  {
    "id": "no_cart_shelf_interaction_in_narrow_aisle",
    "text": "A shopper is forbidden to interact with shelf items while still holding a cart in a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_width": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file_width",
            "between_opposing_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "park_carts_only_in_wide_open_cells",
    "text": "Carts may only be parked in wide open cells, not in narrow passages or beside shelves.",
    "abstraction": {
      "state_properties": {
        "wide_open_parking_cell": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "put_down_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "put_down_cart",
          {
            "not": "wide_open_parking_cell"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_cartless_shelf_shop",
    "text": "After interacting with a shelf while not holding a cart, the shopper is obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "cartless_at_shelf": {
          "and": [
            {
              "not": "hasCart"
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "cartless_shelf_interaction": {
          "pre": {
            "and": [
              "INTERACT",
              "cartless_at_shelf"
            ]
          },
          "post": null
        },
        "pick_up_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartless_shelf_interaction",
      "discharge": "pick_up_cart"
    }
  },
  {
    "id": "exit_with_cart_at_wide_exit",
    "text": "The shopper may exit only from the wide official exit cell and only while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "wide_exit_cell": {
          "and": [
            "at(11,7)",
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "proper_exit_state": {
          "and": [
            "wide_exit_cell",
            "hasCart"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "proper_exit_state"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_aisles_only_for_shelf_tasks",
    "text": "Entering a single-file shelf aisle on foot obliges the shopper to perform a shelf interaction there, rather than using it merely as a shortcut.",
    "abstraction": {
      "state_properties": {
        "single_file_width": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file_width",
            "between_opposing_shelves"
          ]
        },
        "on_foot": {
          "not": "hasCart"
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_on_foot": {
          "pre": {
            "and": [
              "on_foot",
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        },
        "cartless_shelf_interaction": {
          "pre": {
            "and": [
              "on_foot",
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_single_file_shelf_aisle_on_foot",
      "discharge": "cartless_shelf_interaction"
    }
  }
]
